// Goals: 3 active goals generated by stage, progress tracking, rewards, near-goal lines.
import type { Goal, World } from './types';
import { ATTR_HE, POS_WEIGHTS, addNews, clamp, count, ovr, pushHistory, userLeague, userPlayer } from './helpers';
import { nearAttrGoals } from './development';
import type { AttrKey } from './types';

const SEASON_GOALS: Record<string, number> = { ST: 10, W: 7, AM: 6, CM: 3, DM: 2, FB: 1, CB: 2, GK: 0 };

function has(world: World, id: string): Goal | undefined {
  return world.career.goals.find((g) => g.id === id);
}

function mk(world: World, id: string, text: string, kind: Goal['kind'], target: number, reward: string): Goal {
  return { id, text, kind, target, progress: 0, reward, done: false, createdWeek: world.absWeek };
}

/** Candidate goals in priority order. */
function candidates(world: World): Goal[] {
  const u = userPlayer(world);
  const c = world.career;
  const out: Goal[] = [];
  const foreign = (userLeague(world)?.countryCode ?? 'IL') !== 'IL';
  if (u.careerStats.apps < 10) out.push(mk(world, 'apps10', '10 הופעות בקבוצה הבוגרת', 'apps', 10, 'ביטחון +5'));
  if (u.careerStats.goals === 0 && u.pos !== 'GK') out.push(mk(world, 'first_goal', 'השער הראשון בקריירה', 'goals', 1, 'מוניטין +3'));
  const sg = SEASON_GOALS[u.pos];
  if (sg > 0 && u.careerStats.apps >= 5) out.push(mk(world, `season_goals_${world.season.number}`, `${sg} שערים העונה`, 'goals', sg, 'מוניטין +4'));
  if (u.pos === 'GK' && u.careerStats.apps >= 5) out.push(mk(world, `clean_${world.season.number}`, '8 שערים נקיים העונה', 'custom', 8, 'מוניטין +4'));
  if (!foreign && u.age >= 18 && ovr(u) >= 55) out.push(mk(world, 'abroad', 'לעבור לליגה בחו״ל', 'transfer', 1, 'מוניטין +8'));
  if (c.nationalCaps === 0 && ovr(u) >= 58) out.push(mk(world, 'national', 'זימון ראשון לנבחרת', 'national', 1, 'מוניטין +10'));
  if (u.age >= 28 && !c.captain) out.push(mk(world, 'captain', 'להיות קפטן', 'captain', 1, 'כבוד בחדר ההלבשה'));
  if (u.age >= 28) out.push(mk(world, 'mentor', 'להדריך שחקן צעיר (5 ערבי קבוצה)', 'custom', 5, 'אמון המאמן'));
  if (u.careerStats.goals >= 30 && u.pos !== 'GK') out.push(mk(world, 'goals100', '100 שערים בקריירה', 'goals', 100, 'מקום בהיסטוריה'));
  // attribute goal: main attribute to next multiple of 10
  const w = POS_WEIGHTS[u.pos];
  const main = (Object.keys(w) as AttrKey[]).sort((a, b) => (w[b] ?? 0) - (w[a] ?? 0))[0];
  const next = Math.floor(u.attr[main] / 10) * 10 + 10;
  if (next <= 95) out.push(mk(world, `attr_${main}_${next}`, `${ATTR_HE[main]} ${next}`, 'attr', next, 'התמחות חדשה'));
  return out;
}

function progressOf(world: World, g: Goal): number {
  const u = userPlayer(world);
  const c = world.career;
  if (g.id === 'apps10') return u.careerStats.apps;
  if (g.id === 'first_goal' || g.id === 'goals100') return u.careerStats.goals;
  if (g.id.startsWith('season_goals_')) return g.id === `season_goals_${world.season.number}` ? u.stats.goals : g.progress;
  if (g.id.startsWith('clean_')) return g.id === `clean_${world.season.number}` ? u.stats.cleanSheets : g.progress;
  if (g.id === 'abroad') return (userLeague(world)?.countryCode ?? 'IL') !== 'IL' ? 1 : 0;
  if (g.id === 'national') return c.nationalCaps > 0 ? 1 : 0;
  if (g.id === 'captain') return c.captain ? 1 : 0;
  if (g.id === 'mentor') return world.history.flags.mentored ?? 0;
  if (g.id.startsWith('attr_')) {
    const [, key] = g.id.split('_');
    return Math.floor(((u.attr as unknown as Record<string, number>)[key] ?? 0) * 10) / 10;
  }
  return g.progress;
}

/** Update progress, complete goals (with rewards), refill to 3 active. Returns Hebrew lines for completed goals. */
export function updateGoals(world: World): string[] {
  const lines: string[] = [];
  const u = userPlayer(world);
  for (const g of world.career.goals) {
    if (g.done) continue;
    g.progress = progressOf(world, g);
    if (g.progress >= g.target) {
      g.done = true;
      world.career.fame = clamp(world.career.fame + 3, 0, 100);
      u.morale = clamp(u.morale + 5, 0, 100);
      lines.push(`מטרה הושגה: ${g.text}`);
      pushHistory(world, 'goal_done', `השגת את המטרה: ${g.text}`);
      addNews(world, { kind: 'career', headline: `${u.name}: ${g.text}` });
      if (g.kind === 'attr') world.career.specialties = [...new Set([...world.career.specialties, g.text])].slice(-6);
    }
  }
  // drop stale season goals + expired custom goals
  world.career.goals = world.career.goals.filter((g) => {
    if (g.done) return world.absWeek - g.createdWeek < 60;
    if (g.id.startsWith('season_goals_') || g.id.startsWith('clean_')) return g.id.endsWith(`_${world.season.number}`);
    if (g.id.startsWith('ev_')) return world.absWeek - g.createdWeek < 40;
    return true;
  });
  const active = (): Goal[] => world.career.goals.filter((g) => !g.done);
  for (const cand of candidates(world)) {
    if (active().length >= 3) break;
    if (has(world, cand.id)) continue;
    cand.progress = progressOf(world, cand);
    if (cand.progress >= cand.target) continue;
    world.career.goals.push(cand);
  }
  return lines;
}

/** Count goals: the unit of progress, for near-goal lines. Binary goals (a move, a call-up) are not "near". */
function unitOf(g: Goal): { one: string; many: string; fem: boolean } | null {
  if (g.kind === 'apps') return { one: 'הופעה', many: 'הופעות', fem: true };
  if (g.kind === 'goals') return { one: 'שער', many: 'שערים', fem: false };
  if (g.id.startsWith('clean_')) return { one: 'שער נקי', many: 'שערים נקיים', fem: false };
  if (g.id === 'mentor') return { one: 'ערב קבוצה', many: 'ערבי קבוצה', fem: false };
  return null;
}

/** At most 2 near-goal bars. progress and target are always in the same unit (attribute 49.6 of 50, 8 of 10 goals). */
export function nearGoals(world: World): { text: string; progress: number; target: number }[] {
  const out: { text: string; progress: number; target: number; key: string; urgency: number }[] = [];
  for (const n of nearAttrGoals(userPlayer(world))) out.push({ ...n, key: `attr:${n.text.split(':')[0]}`, urgency: n.target - n.progress });
  for (const g of world.career.goals) {
    if (g.done || g.target <= 0) continue;
    const left = Math.round((g.target - g.progress) * 10) / 10;
    if (left <= 0) continue;
    if (g.kind === 'attr') {
      if (left > 1.5) continue;
      const key = `attr:${g.text.replace(/\s*\d+$/, '')}`;
      if (out.some((o) => o.key === key)) continue;
      out.push({ text: `${g.text.replace(/\s*\d+$/, '')}: ${g.progress.toFixed(1)} מתוך ${g.target}`, progress: g.progress, target: g.target, key, urgency: left });
      continue;
    }
    const unit = unitOf(g);
    if (!unit) continue;
    if (left <= 1 || g.progress / g.target >= 0.8) {
      out.push({ text: `${g.text}: עוד ${count(Math.ceil(left), unit.one, unit.many, unit.fem)}`, progress: g.progress, target: g.target, key: g.id, urgency: left / g.target });
    }
  }
  return out.sort((a, b) => a.urgency - b.urgency).slice(0, 2).map(({ text, progress, target }) => ({ text, progress, target }));
}
